"""Untyped lambda calculus: parsing, capture-avoiding substitution,
alpha-equivalence, and normal-order reduction to beta-normal form."""

from __future__ import annotations

import re
import itertools


class StepLimitError(Exception):
    """Raised when normalization exceeds the allowed number of steps."""


class Lam:
    __slots__ = ("var", "body")
    def __init__(self, var, body):
        self.var = var
        self.body = body
    def __eq__(self, other):
        return isinstance(other, Lam) and self.var == other.var and self.body == other.body
    def __repr__(self):
        return f"(\\{self.var}. {show(self.body)})"


class App:
    __slots__ = ("fun", "arg")
    def __init__(self, fun, arg):
        self.fun = fun
        self.arg = arg
    def __eq__(self, other):
        return isinstance(other, App) and self.fun == other.fun and self.arg == other.arg
    def __repr__(self):
        return f"({show(self.fun)} {show(self.arg)})"


class Var:
    __slots__ = ("name",)
    def __init__(self, name):
        self.name = name
    def __eq__(self, other):
        return isinstance(other, Var) and self.name == other.name
    def __repr__(self):
        return self.name


# ---------------------------------------------------------------- parsing

_TOKEN = re.compile(r"[\\()]|[^\s\\()]+")

def tokenize(s):
    return _TOKEN.findall(s)

def parse(s):
    toks = tokenize(s)
    pos = [0]

    def peek():
        return toks[pos[0]] if pos[0] < len(toks) else None

    def next_tok():
        t = toks[pos[0]]
        pos[0] += 1
        return t

    def expect(t):
        got = next_tok()
        assert got == t, f"expected {t!r}, got {got!r}"

    def term():
        t = peek()
        if t == "\\":
            next_tok()
            v = next_tok()
            expect(".")
            body = term()
            return Lam(v, body)
        if t == "(":
            next_tok()
            e = term()
            expect(")")
            return e
        # application chain / single atom
        e = Var(next_tok())
        while True:
            t = peek()
            if t is None or t in "())":
                break
            if t == "\\":
                # allow juxtaposition with a lambda argument: f (\x. x)
                arg = term()
                e = App(e, arg)
                break
            e = App(e, Var(next_tok()))
        return e

    result = term()
    assert pos[0] == len(toks), f"trailing tokens: {toks[pos[0]:]}"
    return result


# ------------------------------------------------------------- printing

def show(t):
    if isinstance(t, Var):
        return t.name
    if isinstance(t, Lam):
        # collect nested lambdas for compact display: \x. \y. e -> \x y. e
        params = []
        body = t
        while isinstance(body, Lam):
            params.append(body.var)
            body = body.body
        return "(\\" + " ".join(params) + ". " + show(body) + ")"
    if isinstance(t, App):
        return "(" + show(t.fun) + " " + show(t.arg) + ")"
    raise TypeError(t)


# ---------------------------------------------- capture-avoiding subst

def fresh_name(base, avoid):
    if base not in avoid:
        return base
    i = 0
    while True:
        candidate = f"{base}{i}" if i else base + "_"
        if candidate not in avoid:
            return candidate
        i += 1


def free_vars(t):
    if isinstance(t, Var):
        return {t.name}
    if isinstance(t, Lam):
        return free_vars(t.body) - {t.var}
    if isinstance(t, App):
        return free_vars(t.fun) | free_vars(t.arg)
    raise TypeError(t)


def subst(t, name, val):
    """Capture-avoiding substitution of `val` for `name` in `t`."""
    if isinstance(t, Var):
        return val if t.name == name else t
    if isinstance(t, App):
        return App(subst(t.fun, name, val), subst(t.arg, name, val))
    if isinstance(t, Lam):
        if t.var == name:
            return t  # shadowed; do nothing
        if t.var not in free_vars(val):
            return Lam(t.var, subst(t.body, name, val))
        # capture: alpha-rename the binder out of the way
        fv = free_vars(val) | (free_vars(t.body) - {name})
        new_var = fresh_name(t.var, fv)
        renamed_body = subst(t.body, t.var, Var(new_var))
        return Lam(new_var, subst(renamed_body, name, val))
    raise TypeError(t)


# ------------------------------------------------------------ alpha-eq

def alpha_eq(t1, t2, b1=frozenset(), b2=frozenset()):
    """True iff t1 and t2 are equal up to renaming of bound variables."""
    if type(t1) is not type(t2):
        return False
    if isinstance(t1, Var):
        if t1.name == t2.name:
            return True
        # both bound by corresponding binders at same depth
        return t1.name in b1 and t2.name in b2 and b1[t1.name] == b2[t2.name] \
            if False else (t1.name in b1 and t2.name in b2)
    if isinstance(t1, Lam):
        # tag binders with a depth counter via dicts
        d1 = dict(b1); d2 = dict(b2)
        key = ("b", len(d1))
        d1[t1.var] = key
        d2[t2.var] = key
        return alpha_eq(t1.body, t2.body, d1, d2)
    if isinstance(t1, App):
        return alpha_eq(t1.fun, t2.fun, b1, b2) and alpha_eq(t1.arg, t2.arg, b1, b2)
    raise TypeError(t1)


def _fresh_counter():
    counter = itertools.count()
    def gen(base="v"):
        return f"{base}{next(counter)}"
    return gen


# ------------------------------------------------- normal-order reduction

def is_beta_redex(t):
    return isinstance(t, App) and isinstance(t.fun, Lam)


def reduce_once(t):
    """Perform one normal-order beta step. Returns (new_term, stepped)."""
    if is_beta_redex(t):
        return subst(t.fun.body, t.fun.var, t.arg), True
    if isinstance(t, App):
        for attr in ("fun", "arg"):
            child, done = reduce_once(getattr(t, attr))
            if done:
                new = App(*((child, t.arg) if attr == "fun" else (t.fun, child)))
                return new, True
        return t, False
    if isinstance(t, Lam):
        body, done = reduce_once(t.body)
        return (Lam(t.var, body), done) if done else (t, False)
    return t, False


def normalize(t, max_steps=2000):
    """Reduce t (normal order) to beta-normal form."""
    steps = 0
    while True:
        if steps >= max_steps:
            raise StepLimitError(f"exceeded {max_steps} reduction steps")
        t, stepped = reduce_once(t)
        if not stepped:
            return t
        steps += 1


# ------------------------------------------------------- Church numerals

ZERO = parse("\\f. \\x. x")


def church(n):
    t = Var("x")
    for _ in range(n):
        t = App(Var("f"), t)
    return Lam("f", Lam("x", t))


SUCC = parse("\\n. \\f. \\x. f (n f x)")
PLUS = parse("\\m. \\n. \\f. \\x. m f (n f x)")
MULT = parse("\\m. \\n. \\f. m (n f)")


def as_int(t):
    """Read a Church numeral back into a Python int."""
    n_app = t
    assert isinstance(n_app, Lam) and isinstance(n_app.body, Lam), show(t)
    f, x = Var("f"), Var("x")
    count = 0
    body = n_app.body.body
    while isinstance(body, App):
        assert body.fun == f
        body = body.arg
        count += 1
    assert body == x
    return count


def apply(f, *args):
    t = f
    for a in args:
        t = App(t, a)
    return t

